  23→// setupTestDir creates a temp directory, changes to it, and returns it.
  24→// It also registers cleanup to restore the original directory.
  25→func setupTestDir(t *testing.T) string {
  26→	t.Helper()
  27→	tmpDir := t.TempDir()
  28→	t.Chdir(tmpDir)
  29→	paths.ClearRepoRootCache()
  30→	return tmpDir
  31→}
